def controller(obs, memory) -> int:
    """
    Staged controller for: go to key, pick it up, go to locked door, unlock/open it, go to goal.
    Returns one action int each call.
    """
    from collections import deque

    # Actions
    TURN_LEFT = 0
    TURN_RIGHT = 1
    FORWARD = 2
    PICKUP = 3
    DROP = 4
    TOGGLE = 5
    DONE = 6

    img = obs['image']  # img[x][y] with x=0..6 left->right, y=0..6 top->bottom
    W, H = 7, 7
    agent_x, agent_y = 3, 6  # agent is always at this cell in egocentric view

    # helpers to safely read a cell
    def in_bounds(x, y):
        return 0 <= x < W and 0 <= y < H

    def cell(x, y):
        if not in_bounds(x, y):
            return (0, 0, 0)
        return img[x][y]  # [object, color, state]

    # what's carried by agent (object at agent cell)
    carried_obj, carried_color, carried_state = cell(agent_x, agent_y)

    # passability test for walking into a cell
    def passable(x, y):
        if not in_bounds(x, y):
            return False
        obj, col, st = cell(x, y)
        # unseen or walls or doors closed/locked or interactive objects block walking
        if obj == 0:
            return False
        if obj == 2:  # wall
            return False
        if obj == 4 and st != 0:  # door but not open
            return False
        # keys/balls/boxes block walking (they must be picked up/moved)
        if obj in (5, 6, 7):
            return False
        # lava (9) is not walkable by design
        if obj == 9:
            return False
        # floor/empty/goal/open-door are walkable
        if obj in (1, 3, 8) or (obj == 4 and st == 0):
            return True
        # default conservative
        return False

    # find cells of a given object type (return list of (x,y,obj,color,state))
    def find_objects(obj_code):
        res = []
        for x in range(W):
            for y in range(H):
                o, c, s = cell(x, y)
                if o == obj_code:
                    res.append((x, y, o, c, s))
        return res

    # Breadth-first search from agent to any of target cells set
    def bfs_to_targets(targets):
        # targets: set of (x,y)
        start = (agent_x, agent_y)
        if start in targets:
            return [start]
        q = deque([start])
        prev = {start: None}
        while q:
            cur = q.popleft()
            cx, cy = cur
            for dx, dy in ((0, -1), (1, 0), (0, 1), (-1, 0)):
                nx, ny = cx + dx, cy + dy
                if not in_bounds(nx, ny):
                    continue
                if (nx, ny) in prev:
                    continue
                # allow stepping into target even if it currently contains a blocking object,
                # but only if that target is indeed the goal cell we want to reach (used for goal).
                if (nx, ny) in targets:
                    prev[(nx, ny)] = cur
                    # reconstruct path
                    path = []
                    node = (nx, ny)
                    while node is not None:
                        path.append(node)
                        node = prev[node]
                    path.reverse()
                    return path
                # otherwise require passable
                if passable(nx, ny):
                    prev[(nx, ny)] = cur
                    q.append((nx, ny))
        return None

    # choose an adjacent (neighbor) cell to an object (for pickup/toggle), prefer reachable ones
    def adjacent_positions(x, y):
        res = []
        for dx, dy in ((0, -1), (1, 0), (0, 1), (-1, 0)):
            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny):
                res.append((nx, ny))
        return res

    def find_reachable_adjacent(obj_x, obj_y):
        cand = set()
        for (nx, ny) in adjacent_positions(obj_x, obj_y):
            # we can stand on the neighbor even if currently occupied by the agent
            # require that we can step onto it (or it is current agent cell)
            if (nx, ny) == (agent_x, agent_y) or passable(nx, ny):
                cand.add((nx, ny))
        if not cand:
            return None, None
        path = bfs_to_targets(cand)
        if path is None:
            return None, None
        # path is list of coordinates from agent to target neighbor
        return path, path[-1]

    # Build a short action subplan to move one cell in direction (dx,dy) relative to current egocentric view:
    # current agent always faces "up" in the egocentric image.
    def actions_to_step(dx, dy):
        # dx,dy are -1..1 ints: (-1,0)=left, (1,0)=right, (0,-1)=forward, (0,1)=back
        if dx == 0 and dy == -1:
            return [FORWARD]
        if dx == 1 and dy == 0:
            return [TURN_RIGHT, FORWARD]
        if dx == -1 and dy == 0:
            return [TURN_LEFT, FORWARD]
        if dx == 0 and dy == 1:
            # two rights (or two lefts) then forward
            return [TURN_RIGHT, TURN_RIGHT, FORWARD]
        # fallback
        return [TURN_RIGHT]

    # Memory initialization
    if memory is None:
        memory = {}
    if 'phase' not in memory:
        memory['phase'] = 1
    if 'plan' not in memory:
        memory['plan'] = []

    # If there is a queued low-level plan, execute next action from it
    if memory.get('plan'):
        act = memory['plan'].pop(0)
        return act

    phase = memory['phase']

    # PHASE 1: go to the key (stand on a cell adjacent south of key so key is in front)
    if phase == 1:
        # if already carrying a key, skip to phase 3 (go to door)
        if carried_obj == 5:
            memory['phase'] = 3
            phase = 3
        else:
            keys = find_objects(5)
            if keys:
                # take the first seen key
                kx, ky, _, kcol, kst = keys[0]
                # if key is directly in front, proceed to pickup phase
                if (3, 5) == (kx, ky):
                    memory['phase'] = 2
                    phase = 2
                else:
                    # find reachable adjacent cell to the key (where agent should stand)
                    path, target = find_reachable_adjacent(kx, ky)
                    if path is None:
                        # cannot reach adjacent cell (blocked); try simple explore: go forward if free else turn right
                        if passable(3, 5):
                            memory['plan'] = [FORWARD]
                        else:
                            memory['plan'] = [TURN_RIGHT]
                        return memory['plan'].pop(0)
                    # path[0] is agent pos; if path length >=2, we need to perform one step toward path[1]
                    if len(path) >= 2:
                        nx, ny = path[1]
                        dx = nx - agent_x
                        dy = ny - agent_y
                        memory['plan'] = actions_to_step(dx, dy)
                        return memory['plan'].pop(0)
                    else:
                        # path length == 1 implies we are already on the target adjacent cell
                        # if key is in front, go to pickup phase, else try a small move to adjust
                        if (kx, ky) == (3, 5):
                            memory['phase'] = 2
                            return controller(obs, memory)
                        # otherwise try forward or rotate to find the key
                        if passable(3, 5):
                            memory['plan'] = [FORWARD]
                        else:
                            memory['plan'] = [TURN_RIGHT]
                        return memory['plan'].pop(0)

    # PHASE 2: pick up the key
    if phase == 2:
        # if already carrying key, move to phase 3
        if carried_obj == 5:
            memory['phase'] = 3
            phase = 3
        else:
            # if key in front, pick it up
            fx, fy = 3, 5
            fo, fc, fs = cell(fx, fy)
            if fo == 5:
                memory['plan'] = [PICKUP]
                return memory['plan'].pop(0)
            # else, try to re-position to be in front of key (maybe misaligned)
            keys = find_objects(5)
            if keys:
                kx, ky, _, _, _ = keys[0]
                path, target = find_reachable_adjacent(kx, ky)
                if path is None:
                    if passable(3, 5):
                        memory['plan'] = [FORWARD]
                    else:
                        memory['plan'] = [TURN_RIGHT]
                    return memory['plan'].pop(0)
                if len(path) >= 2:
                    nx, ny = path[1]
                    dx = nx - agent_x
                    dy = ny - agent_y
                    memory['plan'] = actions_to_step(dx, dy)
                    return memory['plan'].pop(0)
                else:
                    if passable(3, 5):
                        memory['plan'] = [FORWARD]
                    else:
                        memory['plan'] = [TURN_RIGHT]
                    return memory['plan'].pop(0)
            else:
                # Key not visible: simple exploration
                if passable(3, 5):
                    memory['plan'] = [FORWARD]
                else:
                    memory['plan'] = [TURN_RIGHT]
                return memory['plan'].pop(0)

    # PHASE 3: go to the door (stand adjacent so door is in front)
    if phase == 3:
        # if carrying nothing (lost key) we could try to find/pick key again, but assume we have it
        if carried_obj != 5:
            # go back to searching for key
            memory['phase'] = 1
            return controller(obs, memory)
        doors = find_objects(4)
        if not doors:
            # maybe door is out of sight (should be visible); do simple explore through room
            if passable(3, 5):
                memory['plan'] = [FORWARD]
            else:
                memory['plan'] = [TURN_RIGHT]
            return memory['plan'].pop(0)
        # choose first door
        dxo, dyo, _, dcol, dst = doors[0]
        # if door is directly in front, go to unlock phase
        if (3, 5) == (dxo, dyo):
            memory['phase'] = 4
            phase = 4
        else:
            path, target = find_reachable_adjacent(dxo, dyo)
            if path is None:
                if passable(3, 5):
                    memory['plan'] = [FORWARD]
                else:
                    memory['plan'] = [TURN_RIGHT]
                return memory['plan'].pop(0)
            if len(path) >= 2:
                nx, ny = path[1]
                ddx = nx - agent_x
                ddy = ny - agent_y
                memory['plan'] = actions_to_step(ddx, ddy)
                return memory['plan'].pop(0)
            else:
                # already on adjacent cell
                if (dxo, dyo) == (3, 5):
                    memory['phase'] = 4
                    return controller(obs, memory)
                if passable(3, 5):
                    memory['plan'] = [FORWARD]
                else:
                    memory['plan'] = [TURN_RIGHT]
                return memory['plan'].pop(0)

    # PHASE 4: unlock/open the door in front
    if phase == 4:
        fx, fy = 3, 5
        fo, fc, fs = cell(fx, fy)
        # if door is not in front anymore, go back to phase 3
        if fo != 4:
            memory['phase'] = 3
            return controller(obs, memory)
        # if door is locked or closed, toggle it
        if fs != 0:
            # Try toggling (will unlock if key color matches)
            memory['plan'] = [TOGGLE]
            # after toggling, stay in this phase until door reported open
            return memory['plan'].pop(0)
        else:
            # door already open
            memory['phase'] = 5
            phase = 5

    # PHASE 5: go through doorway to the goal
    if phase == 5:
        # First, if front is open door, step forward into it
        fx, fy = 3, 5
        fo, fc, fs = cell(fx, fy)
        if fo == 4 and fs == 0:
            # forward into the doorway
            memory['plan'] = [FORWARD]
            return memory['plan'].pop(0)
        # else, look for the goal in view
        goals = find_objects(8)
        if goals:
            gx, gy, _, gcol, gst = goals[0]
            # If goal is directly in front, move forward onto it
            if (gx, gy) == (3, 5):
                memory['plan'] = [FORWARD]
                return memory['plan'].pop(0)
            # plan path into goal cell (allow stepping onto goal even if treated specially)
            path = bfs_to_targets({(gx, gy)})
            if path is None:
                # cannot pathfind to goal in view; try simple exploration: forward if free else turn
                if passable(3, 5):
                    memory['plan'] = [FORWARD]
                else:
                    memory['plan'] = [TURN_RIGHT]
                return memory['plan'].pop(0)
            if len(path) >= 2:
                nx, ny = path[1]
                dx = nx - agent_x
                dy = ny - agent_y
                memory['plan'] = actions_to_step(dx, dy)
                return memory['plan'].pop(0)
            else:
                # already on goal? (rare since agent on start cell)
                memory['plan'] = [DONE]
                return memory['plan'].pop(0)
        else:
            # Goal not visible yet (maybe just beyond door). Try to move forward if possible to explore.
            if passable(3, 5):
                memory['plan'] = [FORWARD]
            else:
                memory['plan'] = [TURN_RIGHT]
            return memory['plan'].pop(0)

    # Fallback: if nothing matched, try a safe action
    if passable(3, 5):
        return FORWARD
    else:
        return TURN_RIGHT
